shell:
node <<'NODE'
import { readFileSync, writeFileSync } from "node:fs";
import { parseCsv, toCsv, COLUMNS } from "$TMPDIR/pg-eval-O2zGwl/.cursor/scripts/tracker-lib.mjs";

const path = "$TMPDIR/pg-eval-O2zGwl/upgrade/tracker.csv";
const today = "2026-11-04";
const { rows } = parseCsv(readFileSync(path, "utf8"));
const byId = new Map(rows.map((r) => [r.ID, r]));

function set(id, patch) {
  const r = byId.get(id);
  if (!r) throw new Error(`missing ${id}`);
  const prevStatus = r.Status;
  Object.assign(r, patch);
  if (patch.Status && patch.Status !== prevStatus) r["Status since"] = today;
  r["Last checked"] = today;
}

for (const r of rows) {
  if (r["Owner role"] === "Program owner" && r.Owner === "unknown") r.Owner = "Dana Lee";
  if (r["Owner role"] === "DBA" && r.Owner === "unknown") r.Owner = "Sam Ortiz";
  if (r["Owner role"] === "Business approver" && r.Owner === "unknown") r.Owner = "Dana Lee";
  if (!r["Last checked"]) r["Last checked"] = today;
}

set("G0.2", {
  Status: "Needs approval",
  Evidence: "upgrade/results/precheck-shop.txt upgrade/results/precheck-postgres.txt",
  Notes: "Kit checks primary psql coverage errors provenance all pass; gate closes only via gate review",
});
set("G0.3", {
  Status: "Waiting on customer",
  Notes: "Missing gcloud sql operations describe JSON; have precheck-18.json and instances-describe.yaml",
});
set("G0.4", {
  Status: "Not started",
  Notes: "Findings report upgrade/findings/precheck-2026-11-04.md; blockers owned via Finding rows",
});

set("B0-01", {
  Status: "Needs approval",
  Evidence: "reports/code-search.md",
  Notes: "Reported done in handoff 2026-11-03; evidence file not in workspace",
});
set("B0-02", {
  Status: "Needs approval",
  Notes: "Reported done by Alex Kim 2026-11-03; no scan links in handoff",
});
set("B0-03", {
  Status: "Done",
  Evidence: "upgrade/results/precheck-shop.txt upgrade/results/precheck-postgres.txt",
});
set("B0-04", {
  Status: "Waiting on customer",
  Notes: "Missing operations describe JSON",
});
set("B0-05", {
  Status: "Done",
  Evidence: "upgrade/findings/precheck-2026-11-04.md",
});
set("B0-09", {
  Status: "Needs approval",
  Notes: "Window 60m weekend read-write and zero data loss reported in interview 2026-10-21; not in signed decision record",
});
set("D-01", {
  Status: "Needs approval",
  Approver: "Dana Lee",
  Notes: "In-place path reported decided 2026-10-24; call notes https://notes.example-meetings.com/d/abc123 — link needed for Done",
});
set("Q-01", {
  Notes: "was CQ-09; Dana Lee named as window approver in handoff; approval not recorded",
});
set("Q-03", {
  Notes: "Interview 2026-10-21: no data loss allowed; needs business sign-off in decision record",
});
set("Q-05", {
  Notes: "Verified instances-describe.yaml: shop-replica-1 shop-replica-2 shop-pg16-test",
});
set("Q-07", {
  Status: "Waiting on customer",
  Notes: "Code search reported done; repo list not approved in this project",
});

const blank = () => Object.fromEntries(COLUMNS.map((c) => [c, ""]));
const newRows = [
  ["Q-20", "Question", "Which Debezium version supports PostgreSQL 18 for the orders feed?", "G0.5 G1.3", "was CQ-04"],
  ["Q-23", "Question", "Reconcile interview CDC count with catalog slots and publications", "G0.5", "Conflict: interview 2026-10-21 says two CDC consumers only; precheck-shop.txt 4a shows three slots and 4b two publications"],
  ["Q-24", "Question", "Paste gcloud sql operations describe for the POSTGRES_18 precheck operation", "G0.3", "Follow-up from precheck parse"],
].map(([ID, Type, Item, Gates, Notes]) => ({
  ...blank(),
  ID,
  Type,
  Block: "0",
  Stream: Type === "Question" && ID === "Q-24" ? "Discovery" : ID === "Q-20" ? "CDC" : "CDC",
  Item,
  "Done when": ID === "Q-24" ? "operations-describe JSON saved under upgrade/results/" : ID === "Q-20" ? "Version recorded on the Debezium Consumer row" : "Every slot and publication maps to a Consumer row or a drop plan",
  "Owner role": ID === "Q-24" ? "DBA" : "CDC owner",
  Owner: ID === "Q-24" ? "Sam Ortiz" : "unknown",
  Side: "Customer",
  "Run by": "Human",
  Gates,
  Status: "Not started",
  "Last checked": today,
  Notes,
  "Status since": today,
}));

// fix Q-24 stream
newRows.find((r) => r.ID === "Q-20").Stream = "CDC";
newRows.find((r) => r.ID === "Q-23").Stream = "CDC";
newRows.find((r) => r.ID === "Q-24").Stream = "Discovery";

const consumers = [
  ["C-orders-api", "App code", "orders-api", "Priya N", "App team", "primary", "none", "scram", "reported by scan in handoff"],
  ["C-debezium-orders", "CDC", "Debezium orders feed (slot debezium_orders)", "unknown", "CDC owner", "cdc", "debezium unknown pgoutput", "scram", "Data team per interview; publication orders_to_warehouse"],
  ["C-search-feed", "CDC", "search_feed logical slot (decoderbufs)", "unknown", "CDC owner", "cdc", "unknown decoderbufs", "unknown", "Unlisted in interview; publication search_index_feed"],
  ["C-old-migration-test", "CDC", "old_migration_test inactive replication slot", "unknown", "DBA", "cdc", "pgoutput stale", "", "96 GB retained WAL precheck-shop.txt 8b"],
];
for (const [ID, Stream, Item, Owner, role, Path, CDC, Auth, Notes] of consumers) {
  newRows.push({
    ...blank(),
    ID,
    Type: "Consumer",
    Block: "0",
    Stream,
    Item,
    "Done when": "Owner confirms path auth hazards and target support",
    "Owner role": role,
    Owner,
    Side: "Customer",
    "Run by": "Both",
    Gates: ID === "C-orders-api" ? "G0.1" : "G0.5 G0.1",
    Status: "Not started",
    "Last checked": today,
    Notes,
    Repo: "unknown",
    "DB role": ID === "C-debezium-orders" ? "cdc_user" : ID === "C-search-feed" ? "search_cdc" : "unknown",
    Auth: Auth || "unknown",
    Path,
    "Driver and version": "unknown",
    CDC,
    "Hazards found": ID.includes("debezium") ? "MVU deletes slot" : ID === "C-search-feed" ? "non-pgoutput plugin" : ID === "C-old-migration-test" ? "extended WAL" : "",
    "Status since": today,
  });
}

const findings = [
  ["F-6d-01", "Catalog", "6d NOT NULL inheritance on metrics_2026_q3.recorded_at", "Sam Ortiz", "precheck-shop.txt section 6d"],
  ["F-6g-01", "Catalog", "normalize_tags in idx_orders_tags_norm missing pinned search_path", "Sam Ortiz", "precheck-shop.txt section 6g"],
  ["F-8b-01", "CDC", "Stale slot old_migration_test with 96 GB retained WAL", "unknown", "precheck-shop.txt section 8b prework"],
  ["F-4a-01", "CDC", "search_feed uses decoderbufs plugin", "unknown", "precheck-shop.txt section 4a"],
  ["F-pr-01", "CDC", "Provider WARNING logical slots deleted during MVU", "unknown", "upgrade/results/precheck-18.json"],
];
for (const [ID, Stream, Item, Owner, Notes] of findings) {
  newRows.push({
    ...blank(),
    ID,
    Type: "Finding",
    Block: "0",
    Stream,
    Item,
    "Done when": "Fix verified on kit or provider rerun",
    "Owner role": Stream === "Catalog" ? "DBA" : "CDC owner",
    Owner,
    Side: "Customer",
    "Run by": "Both",
    Gates: "G1.1",
    Status: "Not started",
    "Last checked": today,
    Notes,
    "Status since": today,
  });
}

for (const nr of newRows) {
  if (byId.has(nr.ID)) throw new Error(`dup ${nr.ID}`);
  rows.push(nr);
}

writeFileSync(path, toCsv(rows));
console.log("rows", rows.length);
NODE
